import{z as o,x as s,o as e,c as d,q as l,j as t,D as A,d as r,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"查询改写与规划","description":"","frontmatter":{"title":"查询改写与规划","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-query-rewrite-plan.md","filePath":"llm/rag-query-rewrite-plan.md","lastUpdated":1791063341000}'),p={name:"llm/rag-query-rewrite-plan.md"};function F(D,E,C,m,h,u){const B=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="查询改写与规划" tabindex="-1">查询改写与规划 <a class="header-anchor" href="#查询改写与规划" aria-label="Permalink to &quot;查询改写与规划&quot;">​</a></h1><div class="epigraph"><p>改写与规划都是用额外的模型调用买对齐；每一次调用既是延迟，也是新的错误源，开口子之前先量鸿沟。</p><footer>—— Gao 等 HyDE；Trivedi 等 IRCoT；Jeong 等 Adaptive-RAG</footer></div><p><a href="/llm/rag-reranker-engineering">上一课</a>把重排做成有预算的工程，检索侧五课到此齐了。本课转到查询侧：用户的问题与索引对象之间隔着两道鸿沟——词汇鸿沟（口语对文档语域）与结构鸿沟（单跳对多跳）。改写的第一性在<a href="/llm/query-rewrite-hyde">查询改写与 HyDE</a>，多跳循环在<a href="/llm/multi-hop-retrieval">多跳检索</a>，复杂度路由在 <a href="/llm/adaptive-rag">Adaptive-RAG</a>。本课写深一层的工程：干预强度怎么分级、什么时候反向、每跳的停损怎么设。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两道鸿沟对应两类失败。词汇鸿沟：用户问「请求拆成几段预填」，索引里是「chunked prefill」，零召回；改写把口语推回文档流形。</p><p><span class="marginnote">词汇鸿沟可以理解为「你说人话、文档说术语」：两边字面一个词都对不上，检索器按字面找相似，就什么都搜不到。改写的本质是提前做一次翻译——把口语翻译成文档的「方言」，再拿去检索。</span>结构鸿沟：「A 和 B 的作者谁所属机构更早」需要分解、逐跳取证据、再比较；一次检索拿不齐证据链。而改写与规划都是额外的 LLM 调用：每次一次往返的延迟与费用，以及新的错误源——改写偏了比不改更糟，规划错了第一跳，后面全链陪葬。没有分级与停损，这条链会变成不可调试的延迟黑洞。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>干预强度分级，从便宜到贵：查询扩展（加同义词，无模型调用）；多查询改写（一次调用生成 \\(N\\) 个变体，分别检索再融合）；HyDE（一次调用生成假文档，用其嵌入检索，假文档不进上下文）；逐步回退（先问上层概念再落细节）。规划侧：先路由——让小模型或分类器判断直答、单跳、多跳（Adaptive-RAG 的复杂度阶梯），只有多跳进分解流程：拆子问题、逐跳检索、中间抽取宜短、跳数封顶（三到四跳常见上限）。三条纪律贯穿：原查询永远保留一路，与改写路融合而非替换；改写开关按切片评测——「改写对不写对照」，只对直答失败率高的切片开；路由器独立监督，用标注类型而不是模型自述验证。</p>',8)),(e(),t(n,null,{default:A(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20R%7B%22%E5%A4%8D%E6%9D%82%E5%BA%A6%E8%B7%AF%E7%94%B1%22%7D%0A%20%20R%20--%3E%7C%E7%9B%B4%E7%AD%94%7C%20RET%5B%22%E5%8D%95%E6%AC%A1%E6%A3%80%E7%B4%A2%22%5D%0A%20%20R%20--%3E%7C%E5%8D%95%E8%B7%B3%EF%BC%8C%E5%9F%9F%E5%B7%AE%E5%A4%A7%7C%20RW%5B%22%E6%94%B9%E5%86%99%EF%BC%9A%E5%A4%9A%E6%9F%A5%E8%AF%A2%E6%88%96%20HyDE%22%5D%0A%20%20R%20--%3E%7C%E5%A4%9A%E8%B7%B3%7C%20PLAN%5B%22%E5%88%86%E8%A7%A3%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%0A%20%20RW%20--%3E%20FUS%5B%22%E5%8E%9F%E6%9F%A5%E8%AF%A2%20%2B%20%E6%94%B9%E5%86%99%E8%9E%8D%E5%90%88%22%5D%0A%20%20FUS%20--%3E%20RET%0A%20%20PLAN%20--%3E%20H1%5B%22%E9%80%90%E8%B7%B3%EF%BC%9A%E6%A3%80%E7%B4%A2%E2%80%93%E6%8A%BD%E5%8F%96%E2%80%93%E5%86%8D%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20H1%20--%3E%20STOP%7B%22%E8%B7%B3%E6%95%B0%E5%B0%81%E9%A1%B6%20%2F%20%E7%BD%AE%E4%BF%A1%E8%B6%B3%E5%A4%9F%EF%BC%9F%22%7D%0A%20%20STOP%20--%3E%7C%E5%90%A6%7C%20H1%0A%20%20STOP%20--%3E%7C%E6%98%AF%7C%20RET%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"多查询改写里的 \\(N\\) 常取 3 到 5：一次调用把原问题改写成 3 个不同说法，各自检索取回几组结果再融合去重。相当于花 1 次模型调用的钱，换 3 倍的检索覆盖面——检索本身很便宜，所以这笔账通常划算；真正贵的是那一次改写调用。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"改写为什么会在域差大时反向：改写模型把查询推向它先验里见过的文档语域，而你的索引若是内部工单、代码补丁，先验语域离你的文档更远——改写等于把查询推离目标。缩小鸿沟的根本手段是上一单元的域内微调；改写是鸿沟大时的补丁，不是万能前置。规划的错误为什么放大：第一跳检错，中间抽取跟着错，子问题偏离原意，证据链断在中间——每跳都要有停损：跳数上限、逐跳置信阈值、失败回退到原始查询的单次检索。路由为什么必须独立监督：让生成模型自述「这题我需要多跳」，它会倾向于表演复杂度；路由器的错分直接决定延迟与质量，要用人工标注的类型集验收。",-1)),(e(),t(n,null,{default:A(()=>[i(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E7%94%A8%E6%88%B7%E6%9F%A5%E8%AF%A2%EF%BC%8C%E5%8F%A3%E8%AF%AD%22%5D%20--%3E%20C%7B%22%E7%B4%A2%E5%BC%95%E9%87%8C%E7%9A%84%E6%96%87%E6%A1%A3%E6%98%AF%E4%BB%80%E4%B9%88%E8%AF%AD%E5%9F%9F%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E9%80%9A%E7%94%A8%E7%BD%91%E9%A1%B5%E3%80%81%E7%99%BE%E7%A7%91%22%7C%20G%5B%22%E6%94%B9%E5%86%99%E6%8E%A8%E5%90%91%E9%80%9A%E7%94%A8%E4%B9%A6%E9%9D%A2%E8%AF%AD%E5%9F%9F%22%5D%0A%20%20G%20--%3E%20GAIN%5B%22%E6%9F%A5%E8%AF%A2%E4%B8%8E%E6%96%87%E6%A1%A3%E8%B7%9D%E7%A6%BB%E6%8B%89%E8%BF%91%EF%BC%8C%E5%8F%AC%E5%9B%9E%E4%B8%8A%E5%8D%87%22%5D%0A%20%20GAIN%20--%3E%20FUS%5B%22%E4%B8%8E%E5%8E%9F%E6%9F%A5%E8%AF%A2%E8%9E%8D%E5%90%88%E6%A3%80%E7%B4%A2%22%5D%0A%20%20C%20--%3E%7C%22%E5%86%85%E9%83%A8%E5%B7%A5%E5%8D%95%E3%80%81%E4%BB%A3%E7%A0%81%E8%A1%A5%E4%B8%81%22%7C%20B%5B%22%E6%94%B9%E5%86%99%E4%BB%8D%E6%8E%A8%E5%90%91%E9%80%9A%E7%94%A8%E4%B9%A6%E9%9D%A2%E8%AF%AD%E5%9F%9F%22%5D%0A%20%20B%20--%3E%20LOSS%5B%22%E8%B7%9D%E7%A6%BB%E5%8F%8D%E8%80%8C%E6%8B%89%E8%BF%9C%EF%BC%8C%E5%8F%AC%E5%9B%9E%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LOSS%20--%3E%20FB%5B%22%E5%85%B3%E6%8E%89%E6%94%B9%E5%86%99%EF%BC%8C%E8%B5%B0%E5%8E%9F%E6%9F%A5%E8%AF%A2%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">这张图回答的问题是「改写什么时候帮倒忙」。改写模型只认识它训练时见过的通用语域；如果你的索引全是工单、法律条文这类小众文本，改写等于把查询推离了目标。所以开改写前先问一句：我的文档长什么样？</span></p><p><span class="marginnote">一次改写等于一次 LLM 往返，p50 常见加几百毫秒。先统计「不改写的单次检索失败率」：多数系统的失败集中在少数切片（多跳、术语鸿沟、时间约束），只对这些切片开改写，钱花在刀刃上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>改写错误会放大检索偏置（HyDE 课口径）：改写路只在评测证明有增益的切片上开。跳数封顶不是能力声明而是停损：超限即回退并降级回答置信度，不要静默用不完整证据链硬答。中间抽取宜短——长中间结论会把第一跳的幻觉固化为第二跳的条件。规划延迟乘跳数，预算见后面成本课；检索失败的模式清单在收束课汇总。查询侧到齐后，下一课处理索引侧最难的一块：结构化数据。</p><p><span class="marginnote">初学者容易把「三到四跳封顶」当成模型推理能力的上限，实际上它是止损线：跑到上限还没查齐，说明前几跳大概率已经走偏，与其拖着一串断掉的证据硬答，不如回退降级、坦白告诉用户「没查全」。停损保护的是答案的可信度，不是模型的尊严。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两道鸿沟两种药：词汇鸿沟用改写，结构鸿沟用分解规划；都是要付费的模型调用。</li><li>干预强度分级：扩展、多查询、HyDE、逐步回退；先便宜后贵。</li><li>原查询永远保留一路；改写只开在评测证明有增益的切片。</li><li>路由走直答、单跳、多跳阶梯，独立监督，不认模型自述。</li><li>多跳逐跳设停损：封顶、置信阈值、失败回退。</li><li>出处：Gao 等 HyDE；Trivedi 等 IRCoT；Jeong 等 Adaptive-RAG。</li></ul>',7))])}const _=o(p,[["render",F]]);export{T as __pageData,_ as default};
